import React, { useState } from 'react';
import { Modal, Platform, Text, TouchableOpacity, View } from 'react-native';
import { Calendar } from 'react-native-calendars';
import { styles } from './index.styles';

// CalendarDayProps 类型定义（适配 react-native-calendars 所有版本）
interface CalendarDayProps {
    dateString: string; // 日期字符串（YYYY-MM-DD）
    day: string; // 日期数字（如：3）
    month: number; // 月份（0-11）
    year: number; // 年份
    timestamp: number; // 时间戳
    disabled: boolean; // 是否禁用
    selected: boolean; // 是否选中
    marking?: any; // 标记信息
}

// ThemeProps 类型定义（核心样式属性）
interface ThemeProps {
    selectedDayBackgroundColor?: string;
    todayTextColor?: string;
    arrowColor?: string;
    weekdayTextColor?: string;
    'stylesheet.calendar.header'?: {
        week?: any;
        dayHeader?: any;
    };
}

// ========== 1. 工具函数：补全类型 + 优化日期处理 ==========
// 获取中文星期
const getWeekDay = (dateString: string): string => {
    const weeks = ['周日   ', '周一   ', '周二   ', '周三   ', '周四   ', '周五   ', '周六'];
    return weeks[new Date(dateString).getDay()];
};

// 格式化日期显示（如：02月03日）
const formatDateDisplay = (dateString: string): string => {
    const [_, m, d] = dateString.split('-');
    return `${m}月${d}日`;
};

// 计算当前日期 + 1年的日期字符串
const getOneYearLaterDate = (): string => {
    const now = new Date();
    now.setFullYear(now.getFullYear() + 1);
    return now.toISOString().split('T')[0];
};

// ========== 2. 补全 TS 类型 ==========
// 确认回调的返回数据类型
export interface CalendarConfirmData {
    startStr: string; // 入住日期（YYYY-MM-DD）
    startDisplay: string; // 入住日期展示（MM月DD日）
    startWeek: string; // 入住星期（中文）
    endStr: string; // 离店日期（YYYY-MM-DD）
    endDisplay: string; // 离店日期展示（MM月DD日）
    endWeek: string; // 离店星期（中文）
    nights: number; // 入住晚数
}

// 组件 Props 类型
interface CalendarProps {
    visible: boolean;
    onClose: () => void;
    onConfirm: (data: CalendarConfirmData) => void;
}

// 日期标记类型
interface MarkedDateItem {
    startingDay?: boolean;
    endingDay?: boolean;
    color: string;
    textColor: string;
}
type MarkedDates = Record<string, MarkedDateItem>;

// ========== 3. 核心组件 ==========
const Calendar_My = ({ visible, onClose, onConfirm }: CalendarProps) => {
    const [startDate, setStartDate] = useState<string>('');
    const [endDate, setEndDate] = useState<string>('');
    const [markedDates, setMarkedDates] = useState<MarkedDates>({});

    // 当前日期（作为最小可选日期）
    const minDate = new Date().toISOString().split('T')[0];
    // 一年后的日期（作为最大可选日期）
    const maxDate = getOneYearLaterDate();

    // ========== 4. 日期点击逻辑（优化类型 + 边界处理） ==========
    const onDayPress = (day: { dateString: string }) => {
        const dateString = day.dateString;

        // 重置选择：未选起始日期 / 已选完结束日期 → 重新选起始日期
        if (!startDate || (startDate && endDate)) {
            setStartDate(dateString);
            setEndDate('');
            setMarkedDates({
                [dateString]: { startingDay: true, color: '#007AFF', textColor: 'white' }
            });
            return;
        }

        // 选择的结束日期 ≤ 起始日期 → 替换起始日期
        if (dateString <= startDate) {
            setStartDate(dateString);
            setEndDate('');
            setMarkedDates({
                [dateString]: { startingDay: true, color: '#007AFF', textColor: 'white' }
            });
            return;
        }

        // 正常选择结束日期 → 标记日期区间
        setEndDate(dateString);
        const newMarked: MarkedDates = {};
        let curr = new Date(startDate);
        const end = new Date(dateString);

        // 遍历区间内所有日期，标记样式
        while (curr <= end) {
            const str = curr.toISOString().split('T')[0];
            if (str === startDate) {
                newMarked[str] = { startingDay: true, color: '#007AFF', textColor: 'white' };
            } else if (str === dateString) {
                newMarked[str] = { endingDay: true, color: '#007AFF', textColor: 'white' };
            } else {
                newMarked[str] = { color: '#EAF2FF', textColor: '#007AFF' };
            }
            curr.setDate(curr.getDate() + 1);
        }
        setMarkedDates(newMarked);

        // 计算入住晚数
        const nights = Math.ceil(
            (end.getTime() - new Date(startDate).getTime()) / (1000 * 60 * 60 * 24)
        );

        // 触发确认回调
        setTimeout(() => {
            onConfirm({
                startStr: startDate,
                startDisplay: formatDateDisplay(startDate),
                startWeek: getWeekDay(startDate),
                endStr: dateString,
                endDisplay: formatDateDisplay(dateString),
                endWeek: getWeekDay(dateString),
                nights
            });
        }, 300);
    };

    // ========== 5. 自定义星期头部渲染（核心：显示中文） ==========
    const renderWeekDay = (day: string): string => {
        const weekMap: Record<string, string> = {
            'Sun': '周日',
            'Mon': '周一',
            'Tue': '周二',
            'Wed': '周三',
            'Thu': '周四',
            'Fri': '周五',
            'Sat': '周六'
        };
        return weekMap[day] || day;
    };

    // 自定义日历主题（覆盖星期文字样式）
    const calendarTheme: ThemeProps = {
        selectedDayBackgroundColor: '#007AFF',
        todayTextColor: '#007AFF',
        arrowColor: '#007AFF',
        weekdayTextColor: '#666', // 星期文字颜色
        'stylesheet.calendar.header': {
            week: {
                marginTop: 5,
                flexDirection: 'row',
                justifyContent: 'space-between',
                paddingHorizontal: 16
            },
            dayHeader: {
                fontSize: 14,
                fontWeight: '400',
                textAlign: 'center'
            }
        }
    };

    return (
        <Modal visible={visible} animationType="slide" transparent={false}>
            <View style={[styles.modalContainer, { paddingTop: Platform.OS === 'ios' ? 50 : 20 }]}>
                {/* 头部：取消 + 标题 */}
                <View style={styles.modalHeader}>
                    <TouchableOpacity onPress={onClose}>
                        <Text style={styles.cancelText}>取消</Text>
                    </TouchableOpacity>
                    <Text style={styles.modalTitle}>选择入离日期</Text>
                    <View style={{ width: 40 }} />
                </View>

                {/* 核心日历组件：中文星期 + 一年日期范围 */}
                <Calendar
                    markingType={'period'}
                    markedDates={markedDates}
                    onDayPress={onDayPress}
                    minDate={minDate} // 最小日期：今天
                    maxDate={maxDate} // 最大日期：一年后（支持一年内月份切换）
                    theme={calendarTheme}
                    // 自定义星期头部渲染（关键：替换为中文）
                    renderHeader={(date: string) => {
                        // 保留月份标题（如：2026年2月），仅替换星期
                        return (
                            <View>
                                <Text style={{ textAlign: 'center', fontSize: 16, fontWeight: '500', marginVertical: 8 }}>
                                    {new Date(date).getFullYear()}年{new Date(date).getMonth() + 1}月
                                </Text>
                                <View style={calendarTheme['stylesheet.calendar.header']?.week}>
                                    {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => (
                                        <Text
                                            key={day}
                                            style={[calendarTheme['stylesheet.calendar.header']?.dayHeader, { flex: 1 }]}
                                        >
                                            {renderWeekDay(day)}
                                        </Text>
                                    ))}
                                </View>
                            </View>
                        );
                    }}
                    // 可选：自定义日期单元格（增强体验）
                    renderDay={(day: CalendarDayProps) => {
                        return (
                            <Text
                                style={{
                                    textAlign: 'center',
                                    fontSize: 16,
                                    color: day.disabled ? '#ccc' : day.selected ? 'white' : '#333',
                                    fontWeight: day.dateString === minDate ? 'bold' : 'normal'
                                }}
                            >
                                {day.day}
                            </Text>
                        );
                    }}
                />

                {/* 底部提示 */}
                <View style={styles.footerInfo}>
                    <Text style={styles.footerText}>
                        {!startDate
                            ? '请选择入住日期'
                            : !endDate
                                ? '请选择离店日期'
                                : `已选：${formatDateDisplay(startDate)} - ${formatDateDisplay(endDate)} (${Math.ceil((new Date(endDate).getTime() - new Date(startDate).getTime()) / (1000 * 60 * 60 * 24))}晚)`
                        }
                    </Text>
                </View>
            </View>
        </Modal>
    );
};

export default Calendar_My;
